(function(){'use strict';
const E=TitaniumEngine,C=LabCore,S=TitaniumSources,esc=C.esc,$=s=>document.querySelector(s),pct=n=>n===null||n===undefined?'—':Math.round(n*100)+'%',num=n=>n===null||n===undefined?'—':n.toFixed(1);
let project=E.seed(),view='dashboard',page=0,filter={q:'',framework:'',status:'',quick:'',domain:''},dirty=false,toastTimer;
const colors=['#afbdca','#167e69','#dcae62','#bd4053','#6b7fc3'];
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',audit:'<path d="M9 5h10v16H5V5h4m0-2h6v4H9zM9 12h6m-6 4h6"/>',actions:'<path d="M12 3v4m0 10v4M3 12h4m10 0h4"/><circle cx="12" cy="12" r="5"/>',evidence:'<path d="M14 2H6v20h12V6zM14 2v5h5M9 12h6m-6 4h6"/>',catalogs:'<path d="M3 5h7l2 2h9v13H3zM7 11h10m-10 4h7"/>',report:'<path d="M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6z"/>'};
const icon=k=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">'+icons[k]+'</svg>';
const names={dashboard:'Dashboard',audit:'Requisiti & audit',actions:'Piano d’azione',evidence:'Evidenze',catalogs:'Cataloghi',report:'Report'};
const scoped=()=>project.rows.filter(r=>r.inScope);
const catFor=r=>S.catalogs.find(c=>c.id===r.catalogId);
const shortFor=f=>S.catalogs.find(c=>c.name===f)?.short||f;
const badge=(text,type='gray')=>'<span class="pill '+type+'">'+esc(text)+'</span>';
const stateBadge=s=>badge(s,{'Conforme':'teal','Parzialmente conforme':'orange','Non conforme':'red','Non applicabile':'blue'}[s]||'gray');
const pBadge=r=>{const p=E.priority(r);return '<span class="pill '+(p.value>=5?'red':p.value>=3?'orange':'gray')+'" title="'+esc(p.reasons.join('; '))+'">'+p.label+' · '+p.value+'</span>';};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function commit(text){dirty=true;E.auditLog(project,text);}
function safeLink(url,label){try{const u=new URL(url);if(!['https:','http:'].includes(u.protocol))return esc(url);return '<a href="'+esc(u.href)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+'</a>';}catch{return esc(url);}}
function showModal(title,sub,body,footer=''){const d=$('#modal');d.innerHTML='<div class="modal-head"><div><h2>'+title+'</h2><p>'+sub+'</p></div><button class="icon-btn" data-close aria-label="Chiudi">×</button></div><div class="modal-body">'+body+'</div>'+ (footer?'<div class="modal-footer">'+footer+'</div>':'');if(!d.open)d.showModal();d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());}
function modalError(text){let el=$('#modal .error');if(!el){el=document.createElement('div');el.className='error';el.setAttribute('role','alert');$('#modal .modal-body').append(el);}el.textContent=text;el.scrollIntoView({block:'nearest'});}
function confirmAction(title,text,action){showModal(title,'Operazione sul lavoro locale corrente','<p>'+esc(text)+'</p>','<button data-close>Annulla</button><button id="confirm" class="primary">Conferma</button>');$('#confirm').onclick=()=>{action();$('#modal').close();render();};}
function options(values,current,empty){return (empty!==undefined?'<option value="">'+esc(empty)+'</option>':'')+values.map(x=>{const val=Array.isArray(x)?x[0]:x,txt=Array.isArray(x)?x[1]:x;return '<option value="'+esc(val)+'"'+(String(current)===String(val)?' selected':'')+'>'+esc(txt)+'</option>';}).join('');}
function field(k,title,v,type='text'){return '<label>'+title+'<input name="'+k+'" type="'+type+'" value="'+esc(v??'')+'"'+(['maturity','target'].includes(k)?' min="0" max="5" step="1"':'')+'></label>';}
function select(k,title,values,v,empty){return '<label>'+title+'<select name="'+k+'">'+options(values,v,empty)+'</select></label>';}
function area(k,title,v){return '<label class="full">'+title+'<textarea name="'+k+'" maxlength="10000">'+esc(v)+'</textarea></label>';}
function head(title,sub,buttons=''){return '<div class="page-head"><div><span class="eyebrow">TITANIUM / '+names[view]+'</span><h1>'+title+'</h1><p>'+sub+'</p></div><div class="actions">'+buttons+'</div></div>';}
function panel(title,sub,body,extra=''){return '<section class="panel"><div class="panel-head"><div><h2>'+title+'</h2><p>'+sub+'</p></div>'+extra+'</div>'+body+'</section>';}
function kpis(rows){const m=E.metrics(rows);return '<div class="kpis">'+[
 ['Avanzamento',pct(m.completion),m.judged+' valutati · '+m.count['Non applicabile']+' non applicabili',m.completion],
 ['Esito sui valutati',pct(m.judgedScore),'(C + ½ PC) / (C + PC + NC)',m.judgedScore],
 ['Evidenze verificate',pct(m.evidenceCoverage),m.evidence+' di '+m.judged+' valutati · valide alla data odierna',m.evidenceCoverage],
 ['Azioni aperte',m.open,m.late+' scadute · '+m.soon+' entro 30 giorni',null]
 ].map(([label,val,foot,progress])=>'<article class="kpi"><div class="label">'+label+'<span aria-hidden="true">↗</span></div><div class="value">'+val+'</div><div class="foot">'+foot+'</div>'+(progress!==null?'<div class="progress"><i style="width:'+Math.round(progress*100)+'%"></i></div>':'<div class="progress"><i style="width:0%"></i></div>')+'</article>').join('')+'</div>';}
function donut(rows){const m=E.metrics(rows),total=rows.length;let offset=0;const slices=E.status.map((s,i)=>{const length=total?m.count[s]/total*502.65:0;const a='<circle cx="110" cy="110" r="80" fill="none" stroke="'+colors[i]+'" stroke-width="22" stroke-dasharray="'+length+' '+(502.65-length)+'" stroke-dashoffset="'+(-offset)+'" transform="rotate(-90 110 110)"><title>'+esc(s)+': '+m.count[s]+'</title></circle>';offset+=length;return a;}).join('');return '<div class="donut-layout"><svg class="donut" viewBox="0 0 220 220" role="img" aria-label="Distribuzione degli esiti di '+total+' requisiti"><circle cx="110" cy="110" r="80" fill="none" stroke="#edf1f5" stroke-width="22"/>'+slices+'<text x="110" y="109" text-anchor="middle" font-size="35" font-weight="700" fill="#163047">'+total+'</text><text x="110" y="130" text-anchor="middle" font-size="11" fill="#607286">nel perimetro</text></svg><ul class="legend">'+E.status.map((s,i)=>'<li><button data-status="'+esc(s)+'"><span class="dot" style="background:'+colors[i]+'"></span>'+s+'<strong>'+m.count[s]+'</strong></button></li>').join('')+'</ul></div>';}
function frameworks(rows){const fs=[...new Set(rows.map(r=>r.framework))];return fs.length?fs.map(f=>{const rr=rows.filter(r=>r.framework===f),m=E.metrics(rr);return '<div class="bar-row"><span title="'+esc(f)+'">'+esc(shortFor(f))+'</span><div class="stack">'+E.status.map((s,i)=>'<button data-status="'+esc(s)+'" data-frame="'+esc(f)+'" style="width:'+m.count[s]/rr.length*100+'%;background:'+colors[i]+'" title="'+esc(s)+': '+m.count[s]+'" aria-label="'+esc(shortFor(f)+' '+s)+': '+m.count[s]+'"></button>').join('')+'</div><b>'+pct(m.judgedScore)+'</b></div><div class="chart-note" style="margin:0 0 12px 105px">'+m.judged+'/'+m.total+' valutati · '+m.count['Non applicabile']+' NA</div>';}).join(''):'<div class="empty">Nessun framework nel perimetro.</div>';}
function radar(rows){const fs=Object.keys(E.labels),groups=fs.map(f=>rows.filter(r=>r.function===f&&E.judged(r)&&r.maturity!==null)),values=groups.map(a=>a.length?a.reduce((n,r)=>n+r.maturity,0)/a.length:null),targets=groups.map(a=>a.length?a.reduce((n,r)=>n+r.target,0)/a.length:null);const xy=(i,n)=>{const angle=(-90+i*60)*Math.PI/180;return[185+Math.cos(angle)*n*18,130+Math.sin(angle)*n*18];},polygon=ns=>ns.map((n,i)=>xy(i,n).join(',')).join(' ');if(values.every(x=>x===null))return '<div class="empty"><strong>Maturità non ancora valutata</strong>Inserisci valori 0–5 nei requisiti associati a una funzione.</div>';return '<svg class="radar" viewBox="0 0 370 260" role="img" aria-label="Maturità media per funzione; '+fs.map((f,i)=>f+': '+num(values[i])).join(', ')+'">'+[1,2,3,4,5].map(n=>'<polygon points="'+polygon(fs.map(()=>n))+'" fill="none" stroke="#dce5eb" stroke-width="1"/>').join('')+fs.map((f,i)=>{const[x,y]=xy(i,5),[lx,ly]=xy(i,6.3);return'<line x1="185" y1="130" x2="'+x+'" y2="'+y+'" stroke="#dce5eb"/><text x="'+lx+'" y="'+ly+'" fill="#607286" font-size="10" text-anchor="middle">'+f+' · '+num(values[i])+'</text>';}).join('')+(values.every(x=>x!==null)?'<polygon class="surface" points="'+polygon(values)+'"/><polygon class="target" points="'+polygon(targets)+'"/>':'')+values.map((v,i)=>{if(v===null)return'';const[x,y]=xy(i,v),[tx,ty]=xy(i,targets[i]);return '<circle cx="'+x+'" cy="'+y+'" r="4" fill="#087e87"><title>'+E.labels[fs[i]]+': '+num(v)+' su '+groups[i].length+' valutazioni</title></circle><circle cx="'+tx+'" cy="'+ty+'" r="3" fill="#dcae62"/>';}).join('')+'</svg><div class="chart-note"><span class="dot" style="background:#087e87"></span> Attuale &nbsp; <span class="dot" style="background:#dcae62"></span> Obiettivo · scala locale 0–5. Non è un Tier NIST.<br>'+fs.map((f,i)=>f+': '+groups[i].length+' rilevazioni').join(' · ')+'. Le funzioni prive di valutazioni restano senza valore.</div>';}
function actionRows(){return scoped().filter(r=>r.action&&!['Concluso','Annullato'].includes(r.actionStatus));}
function heatmap(){const rows=actionRows(),buckets=['Scaduto','Entro 30 giorni','Nei tempi','Scadenza da definire'];return '<div class="heatmap"><span></span>'+['Scadute','≤ 30 gg','> 30 gg','Senza data'].map(x=>'<span>'+x+'</span>').join('')+['Alta','Media','Bassa'].map((s,si)=>'<span>'+s+'</span>'+buckets.map(b=>{const n=rows.filter(r=>r.severity===s&&C.deadline(r)===b).length;return '<button data-heat="'+s+'|'+b+'" style="background:'+(n?['#bd4053','#dcae62','#cfe8e2'][si]:'#f0f4f6')+';color:'+(n&&si===0?'white':'#294455')+'" aria-label="'+s+', '+b+': '+n+' azioni">'+n+'</button>';}).join('')).join('')+'</div><div class="chart-note">Severità dello scostamento × urgenza della scadenza. È una matrice operativa delle azioni, non una misura di rischio probabilistico.</div>';}
function timeline(){const rows=actionRows(),buckets=[['Scadute',r=>E.days(r.due)<0&&r.due,'Scaduto','red'],['0–7 gg',r=>r.due&&E.days(r.due)>=0&&E.days(r.due)<=7,'week','orange'],['8–30 gg',r=>r.due&&E.days(r.due)>7&&E.days(r.due)<=30,'month',''],['> 30 gg',r=>r.due&&E.days(r.due)>30,'Nei tempi',''],['Senza data',r=>!r.due,'Scadenza da definire','']],counts=buckets.map(b=>rows.filter(b[1]).length),max=Math.max(...counts,1);return '<div class="timeline">'+buckets.map((b,i)=>'<div class="bucket"><strong>'+counts[i]+'</strong><button class="column '+b[3]+'" data-due="'+b[2]+'" style="height:'+Math.max(3,counts[i]/max*110)+'px" aria-label="'+b[0]+': '+counts[i]+' azioni"></button><span>'+b[0]+'</span></div>').join('')+'</div><div class="chart-note">Scadenze rispetto a oggi, '+C.today()+', Europe/Rome. Azioni concluse e annullate escluse.</div>';}
function trend(){const h=project.history.slice(-12),same=h.filter(x=>x.scope===scopeKey(scoped()));if(!same.length)return '<div class="empty"><strong>Nessuna rilevazione per questo perimetro</strong>Registra un punto durante l’audit. Il grafico userà solo rilevazioni effettuate, senza ricostruire uno storico.<br><button class="small" data-act="snapshot">Registra rilevazione</button></div>';const x=i=>45+(same.length===1?125:i/(same.length-1)*270),y=v=>170-v*130;const line=key=>same.map((p,i)=>p[key]===null?'':x(i)+','+y(p[key])).filter(Boolean).join(' ');return '<svg class="linechart" viewBox="0 0 350 215" role="img" aria-label="Andamento delle ultime '+same.length+' rilevazioni per lo stesso perimetro">'+[0,.5,1].map(v=>'<line x1="45" x2="315" y1="'+y(v)+'" y2="'+y(v)+'" stroke="#dce5eb"/><text x="34" y="'+(y(v)+4)+'" text-anchor="end" font-size="10" fill="#607286">'+v*100+'%</text>').join('')+[['completion','#087e87'],['score','#dcae62']].map(([k,c])=>'<polyline points="'+line(k)+'" fill="none" stroke="'+c+'" stroke-width="2"/>'+same.map((p,i)=>p[k]===null?'':'<circle cx="'+x(i)+'" cy="'+y(p[k])+'" r="4" fill="'+c+'"><title>'+p.date+' · '+new Date(p.time).toLocaleTimeString('it-IT',{timeZone:'Europe/Rome'})+' · '+pct(p[k])+'</title></circle>').join('')).join('')+same.map((p,i)=>'<text x="'+x(i)+'" y="194" font-size="9" fill="#607286" text-anchor="middle">'+(same.length<=5?p.date.slice(5):(i===0||i===same.length-1?p.date.slice(5):''))+'</text>').join('')+'</svg><div class="chart-note"><span class="dot" style="background:#087e87"></span> Avanzamento &nbsp; <span class="dot" style="background:#dcae62"></span> Esito sui valutati · '+same.length+' rilevazioni, stesso perimetro. I cambi di perimetro generano serie separate.</div>';}
function scopeKey(rows){return E.scopeKey(rows);}
function insights(){const rows=scoped(),items=[['urgent',rows.filter(r=>E.priority(r).value>=5).length,'Priorità urgenti','Severità, ritardi e qualità delle evidenze determinano la priorità.'],['evidence',rows.filter(r=>E.judged(r)&&!E.evidenceOK(r)).length,'Evidenze da completare','Valutazioni senza un’evidenza verificata e ancora valida.'],['owner',rows.filter(r=>(r.action||E.judged(r))&&!r.owner.trim()).length,'Responsabili da assegnare','Chiarisci la responsabilità di verifica o attuazione.'],['missing-action',rows.filter(r=>['Non conforme','Parzialmente conforme'].includes(r.status)&&!r.action.trim()).length,'Scostamenti senza azione','Trasforma lo scostamento in un’attività con responsabile e scadenza.']];return items.map(([k,n,t,d])=>'<div class="insight"><div class="count">'+n+'</div><div><h3>'+t+'</h3><p>'+d+'</p></div><button class="small" data-quick="'+k+'">Esamina</button></div>').join('');}
function dashboard(){const rows=scoped(),m=E.metrics(rows);return head('La governance, a colpo d’occhio.','Dalle evidenze alle decisioni: un quadro operativo del tuo audit.', '<button data-act="scope">Definisci perimetro</button><button class="primary" data-nav="audit">Apri audit ↗</button>')+'<div class="hero"><div><span class="eyebrow">AUDIT WORKSPACE · DATI SINTETICI INIZIALI</span><h2>'+esc(project.meta.name)+'</h2><p>'+esc(project.meta.scope)+'</p></div><div class="hero-stat">'+m.total+'<small>requisiti nel perimetro</small></div></div>'+kpis(rows)+'<div class="grid">'+panel('Esiti dell’audit','Clicca sulla legenda per esplorare i requisiti.',donut(rows))+panel('Confronto tra framework','Distribuzione degli esiti e punteggio sui soli valutati.',frameworks(rows)+'<div class="chart-note">I cataloghi hanno granularità e scopi diversi: la percentuale descrive l’audit selezionato, senza equivalenze automatiche.</div>')+panel('Maturità e obiettivo','Un confronto per funzione, sui requisiti già valutati.',radar(rows))+panel('Priorità da presidiare','Azioni aperte per severità e scadenza.',heatmap())+panel('Calendario delle azioni','Individua i picchi di lavoro e le scadenze mancanti.',timeline())+panel('Andamento delle rilevazioni','Rilevazioni locali, registrate esplicitamente.',trend(),'<button class="small" data-act="snapshot">Registra punto</button>')+'</div><div style="height:20px"></div>'+panel('Prossime decisioni','Indicazioni trasparenti basate sui dati del lavoro corrente.',insights(),badge('Regole locali · nessuna AI cloud','teal'))+'<p class="footer-note">I dati iniziali sono sintetici. Nessun giudizio di conformità è generato automaticamente. Riferimenti e testi dei cataloghi provengono dalle fonti indicate; indice ISO e schede CIS hanno copertura distinta.</p>';}
function matches(r){const q=filter.q.toLowerCase();if(q&&!([r.code,r.title,r.detail,r.framework,r.evidence,r.evidenceRef,r.action,r.owner,r.gap].join(' ').toLowerCase().includes(q)))return false;if(filter.framework&&r.framework!==filter.framework||filter.status&&r.status!==filter.status||filter.domain&&r.domain!==filter.domain)return false;const k=filter.quick;if(k==='urgent')return E.priority(r).value>=5;if(k==='evidence')return E.judged(r)&&!E.evidenceOK(r);if(k==='owner')return(r.action||E.judged(r))&&!r.owner.trim();if(k==='missing-action')return['Non conforme','Parzialmente conforme'].includes(r.status)&&!r.action.trim();if(k.startsWith('due:')){const b=k.slice(4);return r.action&&!['Concluso','Annullato'].includes(r.actionStatus)&&(b==='week'?r.due&&E.days(r.due)>=0&&E.days(r.due)<=7:b==='month'?r.due&&E.days(r.due)>7&&E.days(r.due)<=30:C.deadline(r)===b);}if(k.startsWith('heat:')){const[s,b]=k.slice(5).split('|');return r.severity===s&&r.action&&!['Concluso','Annullato'].includes(r.actionStatus)&&C.deadline(r)===b;}return true;}
function filtersHTML(){return '<div class="filters"><input id="search" type="search" placeholder="Cerca requisito, evidenza, responsabile…" value="'+esc(filter.q)+'" aria-label="Cerca nei requisiti"><select id="frame-filter" aria-label="Framework">'+options([...new Set(scoped().map(r=>r.framework))],filter.framework,'Tutti i framework')+'</select><select id="status-filter" aria-label="Esito">'+options(E.status,filter.status,'Tutti gli esiti')+'</select><button data-act="clear-filters">Azzera filtri</button></div>'+(filter.quick?'<div class="banner">Filtro operativo: '+esc({'urgent':'Priorità urgenti','evidence':'Evidenze da completare','owner':'Responsabili mancanti','missing-action':'Scostamenti senza azione'}[filter.quick]||filter.quick)+'<button class="small" data-act="clear-filters">Rimuovi</button></div>':'');}
function requirementTable(rows){const maxPage=Math.max(0,Math.ceil(rows.length/25)-1);page=Math.min(page,maxPage);const slice=rows.slice(page*25,(page+1)*25);return rows.length?'<div class="table-scroll"><table class="audit-table"><thead><tr><th>Riferimento</th><th>Requisito / scheda</th><th>Esito</th><th>Evidenza</th><th>Priorità</th><th>Maturità</th></tr></thead><tbody>'+slice.map(r=>'<tr><td class="code">'+esc(r.code)+'<small>'+esc(shortFor(r.framework))+'</small></td><td class="req"><button data-edit="'+esc(r.id)+'">'+esc(r.title)+'</button><small>'+esc(r.domain)+(r.level?' · '+esc(r.level):'')+'</small><p>'+esc(r.gap||r.situation||r.detail||'Valutazione da completare')+'</p></td><td>'+stateBadge(r.status)+'</td><td>'+badge(E.evidenceOK(r)?'Verificata':E.evidenceIssue(r)||'Da raccogliere',E.evidenceOK(r)?'teal':E.judged(r)?'orange':'gray')+'<small>'+esc(r.evidenceRef||'—')+'</small></td><td>'+pBadge(r)+'</td><td>'+(r.maturity===null?'—':r.maturity)+' <small>obiettivo '+r.target+'/5</small></td></tr>').join('')+'</tbody></table></div><div class="pagination"><span>'+rows.length+' risultati · '+(page*25+1)+'–'+Math.min((page+1)*25,rows.length)+'</span><div><button class="small" data-page="-1"'+(!page?' disabled':'')+'>←</button>Pagina '+(page+1)+' di '+(maxPage+1)+'<button class="small" data-page="1"'+(page===maxPage?' disabled':'')+'>→</button></div></div>':'<div class="empty"><strong>Nessun requisito trovato</strong>Modifica i filtri o il perimetro dell’audit.</div>';}
function audit(){return head('Requisiti, evidenze, giudizi.','Ogni valutazione resta tracciabile al catalogo e alla sua versione.','<button data-act="scope">Perimetro</button><button data-act="export-xlsx">Esporta Excel</button><button class="primary" data-act="import">Importa Excel</button>')+panel('Il tuo audit',scoped().length+' requisiti selezionati · '+project.rows.filter(r=>!r.inScope).length+' esclusi',filtersHTML()+'<div id="results">'+requirementTable(scoped().filter(matches))+'</div>');}
function actions(){const rows=actionRows().filter(matches).sort((a,b)=>E.priority(b).value-E.priority(a).value);return head('Dai gap al miglioramento.','Un piano prioritizzato con responsabilità e scadenze, distinto dall’esito del requisito.','<button data-nav="audit">Esamina scostamenti</button><button data-act="export-actions">Esporta piano CSV</button>')+filtersHTML()+'<div class="board">'+['Da avviare','In corso','Concluso'].map(s=>{const rr=s==='Concluso'?scoped().filter(r=>r.action&&r.actionStatus===s&&matches(r)):rows.filter(r=>r.actionStatus===s);return '<section class="lane"><h3>'+s+'<span>'+rr.length+'</span></h3>'+rr.slice(0,60).map(r=>'<article class="action-card"><div class="badge-row">'+pBadge(r)+badge(r.severity,r.severity==='Alta'?'red':'gray')+'</div><p>'+esc(r.action)+'</p><small>'+esc(r.code)+' · '+esc(shortFor(r.framework))+'</small><div class="action-bottom"><span><small>'+esc(r.owner||'Responsabile da assegnare')+'</small><small>'+esc(r.due||'Senza scadenza')+' · '+esc(C.deadline(r))+'</small></span><button class="small" data-edit="'+esc(r.id)+'">Gestisci</button></div></article>').join('')+(rr.length>60?'<p class="chart-note">Mostrate le prime 60 azioni: usa i filtri per le altre.</p>':'')+(!rr.length?'<div class="empty">Nessuna azione.</div>':'')+'</section>';}).join('')+'</div><p class="footer-note">Priorità: severità NC/PC 1–3, azione scaduta +2, responsabile mancante +1, evidenza non verificata/valida +1. Urgente ≥5; alta ≥3. Non è un calcolo di rischio normativo.</p>';}
function evidence(){const rows=scoped().filter(r=>r.evidenceRef||r.evidence).filter(matches),groups=new Map;for(const r of rows){const key=r.evidenceRef||'senza-id-'+r.id;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}return head('Un’evidenza, più collegamenti.','Riutilizza lo stesso identificativo su requisiti diversi, mantenendo giudizi e verifiche indipendenti.','<button data-quick="evidence">Esamina evidenze incomplete</button>')+filtersHTML()+panel('Registro delle evidenze',groups.size+' riferimenti · '+rows.length+' collegamenti nel perimetro',groups.size?'<div class="table-scroll"><table class="audit-table evidence-table"><thead><tr><th>ID / descrizione</th><th>Requisiti collegati</th><th>Verifica per requisito</th><th>Validità</th></tr></thead><tbody>'+[...groups].slice(page*25,(page+1)*25).map(([id,rr])=>'<tr><td><strong>'+esc(id.startsWith('senza-id-')?'Senza ID':id)+'</strong><p>'+esc(rr[0].evidence)+'</p>'+(new Set(rr.map(r=>r.evidence)).size>1?badge('Descrizioni differenti: riesaminare','orange'):'')+'</td><td>'+rr.map(r=>'<button class="small" data-edit="'+esc(r.id)+'">'+esc(r.code)+' · '+esc(shortFor(r.framework))+'</button>').join(' ')+'</td><td>'+rr.map(r=>'<div>'+badge(r.code+': '+(E.evidenceOK(r)?'verificata':E.evidenceIssue(r)),E.evidenceOK(r)?'teal':'orange')+'</div>').join('')+'</td><td>'+rr.map(r=>'<small>'+esc(r.code)+': '+esc(r.evidenceDate||'Data mancante')+' → '+esc(r.evidenceExpiry||'Scadenza non definita')+'</small>').join('')+'</td></tr>').join('')+'</tbody></table></div><div class="pagination"><span>'+groups.size+' evidenze · pagina '+(page+1)+'</span><div><button class="small" data-page="-1"'+(!page?' disabled':'')+'>←</button><button class="small" data-page="1"'+((page+1)*25>=groups.size?' disabled':'')+'>→</button></div></div>':'<div class="empty">Nessuna evidenza registrata per questi filtri.</div>')+'<p class="footer-note">Il registro usa ID di collegamento espliciti. Non copia automaticamente giudizi, allegati o stati fra framework. Sono memorizzate descrizioni e riferimenti, non file binari.</p>';}
function catalogs(){return head('La base del tuo audit.','Cataloghi versionati da fonti ufficiali, con copertura e limiti visibili.','<a href="TITANIUM-template.xlsx" download><button>Template Excel ↓</button></a><button class="primary" data-act="import">Importa catalogo o audit</button>')+'<div class="banner"><span>Fonti recuperate il '+S.checked+'. La demo lavora offline con questa versione dei dati; nessun aggiornamento silenzioso.</span><button class="small" data-act="source-info">Metodo e fonti</button></div><div class="catalog-cards">'+S.catalogs.map(c=>{const present=project.rows.filter(r=>r.catalogId===c.id),selected=present.filter(r=>r.inScope).length;return'<article class="catalog-card">'+badge(c.basis.includes('originali')?'Schede / indice':'Fonte ufficiale',c.basis.includes('originali')?'orange':'teal')+'<h2>'+esc(c.name)+'</h2><span class="version">'+esc(c.version)+'</span><div class="catalog-count">'+c.rows.length+' <small>'+ (c.id==='iso'?'schede e riferimenti':c.id==='cis'?'schede operative':'voci')+'</small></div><p>'+esc(c.note)+'</p><small>'+esc(c.basis)+'</small><div class="catalog-foot">'+safeLink(c.source,'Apri fonte ↗')+'<button class="small '+(!present.length?'primary':'')+'" data-add="'+c.id+'">'+(present.length?selected+' in perimetro':'Aggiungi all’audit')+'</button></div></article>';}).join('')+'</div>'+panel('Integra i tuoi cataloghi','Importa requisiti o aggiorna valutazioni usando il template.', '<p class="method">Puoi importare <strong>Excel .xlsx o CSV</strong> fino a 5 MB e 5.000 requisiti complessivi. La corrispondenza usa <strong>Framework + Versione + Codice</strong>. Prima di applicare i dati vedi nuovi requisiti e aggiornamenti. Le colonne presenti nel file aggiornano i valori corrispondenti, anche quando sono vuote; quelle non presenti conservano i dati attuali.</p><p class="method">Per ISO e CIS, usa solo contenuti che sei autorizzato a utilizzare. Il template permette di integrare il testo completo nel tuo lavoro locale. I testi importati non vengono caricati sul sito o inviati a servizi esterni.</p>');}
function reportContent(full=true){const rows=scoped(),m=E.metrics(rows),fs=[...new Set(rows.map(r=>r.framework))],top=rows.filter(r=>E.priority(r).value>=3).sort((a,b)=>E.priority(b).value-E.priority(a).value).slice(0,10);return '<div class="report-preview"><span class="eyebrow">TITANIUM · REPORT DI AUDIT</span><h2>'+esc(project.meta.name)+'</h2><p><strong>Perimetro:</strong> '+esc(project.meta.scope)+'<br><strong>Auditor:</strong> '+esc(project.meta.auditor)+' · <strong>Data audit:</strong> '+esc(project.meta.date)+'<br><strong>Generato:</strong> '+C.today()+' · Europe/Rome · TITANIUM '+S.version+'</p><div class="report-stats"><span><strong>'+pct(m.completion)+'</strong>Avanzamento</span><span><strong>'+pct(m.judgedScore)+'</strong>Esito sui valutati</span><span><strong>'+pct(m.evidenceCoverage)+'</strong>Evidenze verificate</span><span><strong>'+m.open+'</strong>Azioni aperte</span></div><h3>Risultati per catalogo</h3><table><thead><tr><th>Framework / versione</th><th>Perimetro</th><th>C / PC / NC / NA / NV</th><th>Esito</th></tr></thead><tbody>'+fs.map(f=>{const rr=rows.filter(r=>r.framework===f),x=E.metrics(rr);return'<tr><td>'+esc(f)+'<br>'+esc([...new Set(rr.map(r=>r.version))].join(', '))+'</td><td>'+rr.length+'</td><td>'+[x.count.Conforme,x.count['Parzialmente conforme'],x.count['Non conforme'],x.count['Non applicabile'],x.count['Da valutare']].join(' / ')+'</td><td>'+pct(x.judgedScore)+'</td></tr>';}).join('')+'</tbody></table><h3 style="margin-top:22px">Priorità operative</h3>'+(top.length?'<table><thead><tr><th>Requisito</th><th>Priorità e motivazione</th><th>Azione / owner / scadenza</th></tr></thead><tbody>'+top.map(r=>'<tr><td>'+esc(r.code)+'<br>'+esc(shortFor(r.framework))+'</td><td>'+esc(E.priority(r).label)+' · '+E.priority(r).value+'<br>'+esc(E.priority(r).reasons.join('; '))+'</td><td>'+esc(r.action||'Da definire')+'<br>'+esc(r.owner||'Da assegnare')+' · '+esc(r.due||'Senza data')+'</td></tr>').join('')+'</tbody></table>':'<p>Nessuna priorità alta o urgente secondo le regole locali.</p>')+'<h3 style="margin-top:22px">Metodo e limiti</h3><p class="method">Avanzamento = (C + PC + NC + NA) / totale. Esito sui valutati = (C + 0,5 × PC) / (C + PC + NC); NV e NA esclusi. Indicatore storico TITANIUM = '+pct(m.score)+' sul totale applicabile, inclusi NV; distinto dal punteggio sui valutati. Nessun punteggio costituisce un’attestazione di conformità. Maturità 0–5 assegnata dall’auditor, senza equivalenza ai Tier NIST. Evidenze verificate = valutati con descrizione, verifica e validità alla data di generazione. Le priorità derivano da severità (1–3), ritardo (+2), owner mancante (+1), evidenza incompleta (+1). Urgente ≥5; alta ≥3. Non è un calcolo di rischio quantitativo.</p><h3>Fonti e copertura</h3>'+[...new Set(rows.map(r=>r.catalogId))].map(id=>{const c=S.catalogs.find(x=>x.id===id);return c?'<p class="method"><strong>'+esc(c.name)+' · '+esc(c.version)+'</strong><br>'+esc(c.note)+'<br>'+safeLink(c.source,c.source)+' · verificato '+c.checked+'</p>':'<p class="method">Catalogo utente: responsabilità della fonte e dei diritti di utilizzo a cura dell’importatore.</p>';}).join('')+'<p class="method">Demo iniziale sintetica. I dati importati e i giudizi sono responsabilità dell’auditor. Nessun dato è salvato sul cloud. Il report riguarda l’intero perimetro selezionato; i filtri di consultazione non lo restringono.</p>'+(full?'<h3 style="margin-top:24px">Dettaglio dei '+rows.length+' requisiti</h3>'+rows.map(r=>'<article class="report-record"><h3>'+esc(r.code)+' · '+esc(r.title)+'</h3><small>'+esc(r.framework)+' · '+esc(r.version)+' · '+esc(r.basis)+'</small><p><strong>Esito:</strong> '+esc(r.status)+' · <strong>Maturità:</strong> '+(r.maturity??'NV')+'/5 · <strong>Obiettivo:</strong> '+r.target+'/5</p>'+(r.naReason?'<p><strong>Non applicabilità:</strong> '+esc(r.naReason)+'</p>':'')+'<p><strong>Situazione:</strong> '+esc(r.situation||'Non documentata')+'</p><p><strong>Evidenza:</strong> '+esc(r.evidence||'Non registrata')+' · '+esc(r.evidenceRef||'Senza ID')+' · '+esc(r.evidenceState)+' · '+esc(r.evidenceDate||'Data non definita')+' → '+esc(r.evidenceExpiry||'Validità non definita')+'</p>'+(r.gap?'<p><strong>Scostamento:</strong> '+esc(r.gap)+' · '+esc(r.severity)+'</p>':'')+(r.action?'<p><strong>Azione:</strong> '+esc(r.action)+' · '+esc(r.owner||'Owner non assegnato')+' · '+esc(r.due||'Senza data')+' · '+esc(r.actionStatus)+'</p>':'')+(r.notes?'<p><strong>Note:</strong> '+esc(r.notes)+'</p>':'')+'<small>Fonte: '+safeLink(r.source,r.source)+' · ultimo riesame '+esc(r.reviewed||'non registrato')+'</small></article>').join(''):'')+'</div>';}
function report(){return head('Un report pronto al riesame.','Riepilogo per la direzione o dettaglio completo, con fonti, metodologia ed evidenze.','<button data-act="export-xlsx">Esporta dati Excel</button><button class="primary" data-act="print">Stampa / PDF</button>')+panel('Dati dell’audit','Questi campi vengono riportati nelle esportazioni.', '<form id="meta-form" class="meta-form">'+field('name','Nome audit',project.meta.name)+field('scope','Perimetro',project.meta.scope)+field('auditor','Auditor',project.meta.auditor)+field('date','Data audit',project.meta.date,'date')+'</form><div class="dialog-note"><label class="check-label"><input type="checkbox" id="report-full" checked> Includi il dettaglio di tutti i requisiti nel perimetro</label></div>')+panel('Anteprima del riepilogo','La stampa include metodologia e fonti; il dettaglio è opzionale.',reportContent(false));}
function render(){const m=E.metrics(scoped());$('#app').innerHTML='<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-icon" aria-hidden="true">T</span><div><strong>TITANIUM</strong><small>AUDIT & GOVERNANCE</small></div></div><nav class="nav" aria-label="Navigazione principale">'+Object.entries(names).map(([k,n])=>'<button data-nav="'+k+'" class="'+(view===k?'active':'')+'"'+(view===k?' aria-current="page"':'')+'>'+icon(k)+n+(k==='actions'?'<span class="num">'+m.open+'</span>':'')+'</button>').join('')+'</nav><div class="side-bottom"><strong><span class="online-dot"></span>Laboratorio locale</strong><p>Dati nella sola sessione.<br>Scarica il lavoro per conservarlo.</p><p>'+'<span>TITANIUM</span>'+'<br>GRC Tools & Lab · v'+S.version+'</p></div></aside><main class="main"><header class="topbar"><span class="breadcrumb">GRC Tools & Lab <span aria-hidden="true"> / </span><b>'+names[view]+'</b></span><div class="top-actions"><span class="session">'+(dirty?'Modifiche nella sessione':'Sessione locale')+'</span><button class="small" data-act="open">Apri lavoro</button><button class="small" data-act="save">Salva lavoro ↓</button><button class="small" data-act="new">Nuovo audit</button></div></header><div class="content appear" id="content" tabindex="-1">'+({dashboard,audit,actions,evidence,catalogs,report}[view])()+'</div></main></div>';bind();}
function refreshResults(){if(view==='audit')$('#results').innerHTML=requirementTable(scoped().filter(matches));else{const search=$('#search'),pos=search?.selectionStart;render();if(search){$('#search').focus();$('#search').setSelectionRange(pos,pos);}}}
function bind(){const search=$('#search');if(search)search.oninput=()=>{filter.q=search.value;page=0;refreshResults();};const f=$('#frame-filter');if(f)f.onchange=()=>{filter.framework=f.value;page=0;refreshResults();};const st=$('#status-filter');if(st)st.onchange=()=>{filter.status=st.value;page=0;refreshResults();};const meta=$('#meta-form');if(meta)meta.onchange=()=>{const d=new FormData(meta),next={};for(const k of ['name','scope','auditor','date'])next[k]=String(d.get(k)||'').slice(0,2000);if(!C.validDate(next.date)){toast('Inserisci una data audit valida.');return;}project.meta=next;commit('Aggiornati i dati generali dell’audit.');};}
function navigate(k){view=k;page=0;render();window.scrollTo({top:0,behavior:'instant'});}
function quick(k){filter.quick=k;filter.status='';page=0;navigate('audit');}
function edit(id){const r=project.rows.find(x=>x.id===id);if(!r)return;const cat=catFor(r),note=cat?cat.note:'';showModal(esc(r.code)+' · Valutazione',esc(r.framework)+' · '+esc(r.version),'<h3>'+esc(r.title)+'</h3>'+(r.detail?'<p class="method">'+esc(r.detail).replace(/\n/g,'<br>')+'</p>':'')+(r.measure?'<p class="method"><strong>Misura:</strong> '+esc(r.measure)+'</p>':'')+'<div class="dialog-note">'+esc(r.basis)+' · '+safeLink(r.source,'Apri fonte ufficiale ↗')+'<br>'+esc(note)+'</div><form id="eval-form"><div class="form-grid">'+select('status','Giudizio di audit',E.status,r.status)+select('severity','Severità dello scostamento',['Bassa','Media','Alta'],r.severity)+select('maturity','Maturità attuale (scala locale)',[0,1,2,3,4,5],r.maturity,'Non valutata')+select('target','Obiettivo di maturità',[0,1,2,3,4,5],r.target)+area('situation','Situazione osservata',r.situation)+area('naReason','Motivazione della non applicabilità (obbligatoria per NA)',r.naReason)+'</div><div class="section-label">Evidenze e verifica</div><div class="form-grid">'+field('evidenceRef','ID evidenza condivisibile',r.evidenceRef)+select('evidenceState','Stato evidenza',E.evidenceStates,r.evidenceState)+area('evidence','Descrizione / riferimento dell’evidenza',r.evidence)+field('evidenceDate','Data evidenza',r.evidenceDate,'date')+field('evidenceExpiry','Scadenza / prossimo riesame',r.evidenceExpiry,'date')+'</div><div class="section-label">Scostamento e piano d’azione</div><div class="form-grid">'+area('gap','Scostamento rilevato',r.gap)+area('action','Azione di miglioramento',r.action)+field('owner','Responsabile',r.owner)+field('due','Scadenza azione',r.due,'date')+select('actionStatus','Stato dell’azione',['Da avviare','In corso','Concluso','Annullato'],r.actionStatus)+select('function','Funzione per il radar',Object.entries(E.labels).map(([k,n])=>[k,k+' · '+n]),r.function,'Non associata')+area('notes','Note di audit',r.notes)+'</div></form><div class="dialog-note">Chiudere un’azione non cambia il giudizio di audit. “Verificate” è una conferma dell’auditor; non viene attribuita dal sistema. '+esc(E.priority(r).reasons.join('; '))+'</div>','<button data-close>Annulla</button><button id="save-eval" class="primary">Salva valutazione</button>');$('#save-eval').onclick=()=>{try{const d=new FormData($('#eval-form')),next=C.clone(r);for(const k of ['status','severity','situation','naReason','evidenceRef','evidenceState','evidence','evidenceDate','evidenceExpiry','gap','action','owner','due','actionStatus','function','notes'])next[k]=String(d.get(k)||'');next.maturity=d.get('maturity')===''?null:Number(d.get('maturity'));next.target=Number(d.get('target'));next.reviewed=C.today();E.validateRow(next);project.rows[project.rows.indexOf(r)]=next;commit('Valutazione aggiornata: '+r.framework+' / '+r.code);$('#modal').close();render();toast('Valutazione aggiornata.');}catch(err){modalError(err.message);}};}
function scopeModal(catalogId=''){let scopeQ='',scopeFramework=catalogId?S.catalogs.find(c=>c.id===catalogId)?.name||'':'',level='Tutti';const choices=new Map(project.rows.map(r=>[r.id,r.inScope]));showModal('Definisci il perimetro','Le esclusioni restano nel file di lavoro e conservano le valutazioni.','<div class="filters"><input id="scope-search" type="search" placeholder="Cerca nel catalogo" aria-label="Cerca nel perimetro"><select id="scope-frame" aria-label="Framework del perimetro">'+options([...new Set(project.rows.map(r=>r.framework))],scopeFramework,'Tutti i framework')+'</select></div><div class="filters"><select id="scope-level" aria-label="Profilo RUC">'+options(['Tutti','Ordinari','Critici','Strategici'],'Tutti')+'</select><button class="small" id="scope-all">Includi risultati</button><button class="small" id="scope-none">Escludi risultati</button></div><p class="chart-note">Profilo RUC: Critici include Ordinari; Strategici include entrambi. Il filtro identifica i requisiti tecnici, non determina l’applicabilità normativa. Conferma esplicitamente inclusioni ed esclusioni.</p><div id="scope-count" class="chart-note"></div><div class="framework-picker" id="scope-results"></div>','<button data-close>Annulla</button><button id="save-scope" class="primary">Applica perimetro</button>');const rr=()=>project.rows.filter(r=>(!scopeFramework||r.framework===scopeFramework)&&(!scopeQ||[r.code,r.title,r.framework].join(' ').toLowerCase().includes(scopeQ))&&(level==='Tutti'||!r.level||['Ordinari',...(level==='Critici'||level==='Strategici'?['Critici']:[]),...(level==='Strategici'?['Strategici']:[])].includes(r.level)));function draw(){const a=rr();$('#scope-count').textContent=a.length+' risultati · '+[...choices.values()].filter(Boolean).length+' requisiti selezionati in totale';$('#scope-results').innerHTML=a.slice(0,250).map(r=>'<label class="pick-row"><input type="checkbox" data-scope-id="'+esc(r.id)+'"'+(choices.get(r.id)?' checked':'')+'><span class="text"><strong>'+esc(r.code)+' · '+esc(r.title)+'</strong><p>'+esc(shortFor(r.framework))+' · '+esc(r.level||r.domain)+'</p></span></label>').join('')+(a.length>250?'<div class="chart-note">Mostrati i primi 250. Includi/Escludi risultati agisce su tutti i '+a.length+' risultati filtrati.</div>':'');$('#scope-results').onchange=e=>{if(e.target.dataset.scopeId){choices.set(e.target.dataset.scopeId,e.target.checked);$('#scope-count').textContent=a.length+' risultati · '+[...choices.values()].filter(Boolean).length+' selezionati';}};}
$('#scope-search').oninput=e=>{scopeQ=e.target.value.toLowerCase();draw();};$('#scope-frame').onchange=e=>{scopeFramework=e.target.value;draw();};$('#scope-level').onchange=e=>{level=e.target.value;draw();};$('#scope-all').onclick=()=>{rr().forEach(r=>choices.set(r.id,true));draw();};$('#scope-none').onclick=()=>{rr().forEach(r=>choices.set(r.id,false));draw();};$('#save-scope').onclick=()=>{project.rows.forEach(r=>r.inScope=choices.get(r.id));commit('Perimetro aggiornato: '+scoped().length+' requisiti.');filter={q:'',framework:'',status:'',quick:'',domain:''};page=0;$('#modal').close();render();};draw();}
function addCatalog(id){if(project.rows.some(r=>r.catalogId===id)){scopeModal(id);return;}const cat=S.catalogs.find(c=>c.id===id),existing=new Set(project.rows.map(C.key)),add=E.fromCatalog(id).filter(r=>!existing.has(C.key(r)));showModal('Aggiungi '+esc(cat.name),esc(cat.version),'<p>'+esc(cat.note)+'</p><p>'+add.length+' nuove voci verranno aggiunte come <strong>Da valutare</strong>.</p>','<button data-close>Annulla</button><button class="primary" id="add-confirm">Aggiungi all’audit</button>');$('#add-confirm').onclick=()=>{if(project.rows.length+add.length>5000){modalError('Il limite è 5.000 requisiti.');return;}project.rows.push(...add);commit('Aggiunto catalogo '+cat.name+': '+add.length+' voci.');$('#modal').close();render();toast('Catalogo aggiunto. Definisci il perimetro prima della valutazione.');};}
function pickFile(accept,fn){document.getElementById('titanium-file-picker')?.remove();const f=document.createElement('input');f.id='titanium-file-picker';f.type='file';f.accept=accept;f.hidden=true;f.onchange=()=>{const file=f.files[0];f.remove();if(file)fn(file);};f.addEventListener('cancel',()=>f.remove(),{once:true});document.body.append(f);f.click();}
async function importFile(file){try{if(file.size>5e6)throw Error('Il file supera 5 MB.');let sheets;if(/\.xlsx$/i.test(file.name))sheets=await LabCatalog.readXLSX(file);else if(/\.csv$/i.test(file.name))sheets=[{name:'CSV',rows:LabCatalog.parseCSV(await file.text())}];else throw Error('Usa un file .xlsx o .csv.');const eligible=sheets.filter(s=>{try{return!!E.detect(s.rows);}catch{return false;}});if(!eligible.length)throw Error('Nessun foglio con Codice e Requisito. Usa il template TITANIUM.');importModal(file.name,eligible);}catch(err){toast(err.message);}}
function importModal(filename,sheets){let detection,preview=null;showModal('Importa dati audit',esc(filename)+' · anteprima prima dell’applicazione','<div class="form-grid">'+select('sheet','Foglio',sheets.map((s,i)=>[i,s.name]),0)+select('mode','Modalità',[['merge','Aggiorna esistenti e aggiungi nuovi'],['append','Solo aggiungi (rifiuta duplicati)']],'merge')+field('defaultFramework','Framework predefinito','Catalogo utente')+field('defaultVersion','Versione predefinita','1.0')+'</div><div class="dialog-note">La chiave è Framework + Versione + Codice. Le colonne presenti aggiornano anche i valori vuoti: controlla l’anteprima. L’importazione viene applicata in blocco solo dopo la validazione.</div><div id="import-map" class="mapping-grid"></div><div id="import-preview"></div>','<button data-close>Annulla</button><button id="check-import">Verifica anteprima</button><button id="apply-import" class="primary" disabled>Applica dati</button>');function mapping(){detection=E.detect(sheets[Number($('#modal [name=sheet]').value)].rows);$('#import-map').innerHTML=Object.entries(E.fields).map(([k,label])=>select('map-'+k,label,[[-1,'Non presente / conserva'],...detection.header.map((h,i)=>[i,h||'Colonna '+(i+1)])],detection.map[k]??-1)).join('');invalidate();}function invalidate(){preview=null;$('#apply-import').disabled=true;$('#import-preview').innerHTML='';$('#modal .error')?.remove();}$('#modal').onchange=e=>{if(e.target.name==='sheet')mapping();else invalidate();};$('#check-import').onclick=()=>{try{const map=Object.fromEntries(Object.keys(E.fields).map(k=>[k,Number($('#modal [name=map-'+k+']').value)])),defaults={framework:$('#modal [name=defaultFramework]').value.trim(),version:$('#modal [name=defaultVersion]').value.trim()};if(map.code<0||map.title<0)throw Error('Mappa almeno Codice e Requisito.');const mapped=Object.values(map).filter(x=>x>=0);if(new Set(mapped).size!==mapped.length)throw Error('Una colonna non può essere usata per due campi.');preview=E.importRows(detection.data,map,defaults,project,$('#modal [name=mode]').value);$('#modal .error')?.remove();const keys=new Set(detection.data.map(x=>JSON.stringify([map.framework>=0?String(x[map.framework]??'').trim():defaults.framework,map.version>=0?String(x[map.version]??'').trim():defaults.version,String(x[map.code]??'').trim()]))),changed=preview.project.rows.filter(r=>keys.has(C.key(r)));$('#import-preview').innerHTML='<div class="banner">'+preview.added+' nuovi requisiti · '+preview.updated+' aggiornamenti · '+(preview.added+preview.updated)+' righe valide</div><p class="chart-note">Prime 8 righe dopo l’importazione:</p><div class="table-scroll"><table class="preview-table"><thead><tr><th>Framework</th><th>Codice</th><th>Esito</th><th>Evidenza</th><th>Owner</th><th>Scadenza</th></tr></thead><tbody>'+changed.slice(0,8).map(r=>'<tr><td>'+esc(r.framework)+'</td><td>'+esc(r.code)+'</td><td>'+esc(r.status)+'</td><td>'+esc(r.evidenceState)+'</td><td>'+esc(r.owner)+'</td><td>'+esc(r.due)+'</td></tr>').join('')+'</tbody></table></div>';$('#apply-import').disabled=false;}catch(err){preview=null;$('#apply-import').disabled=true;modalError(err.message);}};$('#apply-import').onclick=()=>{if(!preview)return;project=preview.project;dirty=true;$('#modal').onchange=null;$('#modal').close();render();toast('Importazione applicata: '+preview.added+' nuovi, '+preview.updated+' aggiornati.');};mapping();}
async function exportXLSX(){const all=[Object.values(E.fields),...project.rows.map(r=>Object.keys(E.fields).map(k=>k==='inScope'?(r[k]?'Si':'No'):r[k]))],xmlEsc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c])).replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g,''),col=n=>{let s='';for(n++;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s;};const zip=new JSZip();zip.file('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>');zip.file('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');zip.file('xl/workbook.xml','<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Audit" sheetId="1" r:id="rId1"/></sheets></workbook>');zip.file('xl/_rels/workbook.xml.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');zip.file('xl/styles.xml','<?xml version="1.0"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Arial"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Arial"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF103047"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="2"><xf fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf><xf fontId="1" fillId="2" borderId="0" xfId="0" applyAlignment="1"><alignment wrapText="1"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>');zip.file('xl/worksheets/sheet1.xml','<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0" showGridLines="0"><pane ySplit="1" xSplit="3" topLeftCell="D2" activePane="bottomRight" state="frozen"/></sheetView></sheetViews><cols>'+Object.keys(E.fields).map((k,i)=>'<col min="'+(i+1)+'" max="'+(i+1)+'" width="'+(['title','evidence','gap','action','situation'].includes(k)?50:22)+'" customWidth="1"/>').join('')+'</cols><sheetData>'+all.map((r,i)=>'<row r="'+(i+1)+'">'+r.map((v,j)=>'<c r="'+col(j)+(i+1)+'" s="'+(i===0?1:0)+'"'+(typeof v==='number'?' t="n"><v>'+v+'</v>':' t="inlineStr"><is><t xml:space="preserve">'+xmlEsc(v)+'</t></is>')+'</c>').join('')+'</row>').join('')+'</sheetData><autoFilter ref="A1:'+col(all[0].length-1)+all.length+'"/></worksheet>');const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE'});C.download('TITANIUM-audit.xlsx',blob,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');toast('Excel esportato. Per conservare anche lo storico usa Salva lavoro.');}
function sourceInfo(){showModal('Fonti, metodo, copertura','Dati recuperati il '+S.checked+' · versioni congelate nella demo','<p class="method">Il caricamento iniziale è offline. Aprire una fonte è una navigazione esplicita al sito ufficiale, non un invio di dati audit. Nessun catalogo viene aggiornato automaticamente.</p><div class="link-list">'+S.catalogs.map(c=>'<p><strong>'+esc(c.name)+' · '+esc(c.version)+'</strong><br>'+esc(c.note)+'<br>'+safeLink(c.source,'Fonte ufficiale ↗')+'</p>').join('')+'</div><div class="section-label">Modelli di riferimento</div><p class="method">Flusso assessment → evidenza → azione, ispirato alla documentazione di Microsoft Purview Compliance Manager. Confronto attuale/obiettivo ispirato ai profili organizzativi NIST CSF; scala di maturità originale 0–5. Nessun punteggio o marchio di certificazione viene riprodotto.</p><div class="link-list">'+safeLink('https://learn.microsoft.com/en-us/purview/compliance-manager-assessments','Microsoft · assessment e azioni')+safeLink('https://tsapps.nist.gov/publication/get_pdf.cfm?pub_id=957411','NIST · profili attuale/obiettivo')+'</div><p class="method">NIST SP800-53 include controlli e miglioramenti attivi dalla release OSCAL 5.2.0. Le voci ritirate sono escluse. RUC include punti codificati degli allegati 2 e 3: altre clausole e allegato 4 devono essere verificati separatamente nel PDF.</p>');}
const actionsMap={scope:()=>scopeModal(),save:()=>{E.validate(project);C.download('TITANIUM-lavoro.json',JSON.stringify(project,null,2));dirty=false;render();toast('File di lavoro scaricato.');},open:()=>pickFile('.json',async f=>{try{if(f.size>10e6)throw Error('File troppo grande.');const p=E.validate(JSON.parse(await f.text()));confirmAction('Apri file di lavoro','Il file sostituirà il lavoro di questa sessione. Salva prima eventuali modifiche da conservare.',()=>{project=p;dirty=false;filter={q:'',framework:'',status:'',quick:'',domain:''};});}catch(e){toast(e.message);}}),new:()=>{showModal('Nuovo audit','Parte senza valutazioni sintetiche. Scegli un catalogo iniziale.','<div class="form-grid">'+field('newName','Nome audit','Nuovo audit')+select('newCatalog','Catalogo iniziale',S.catalogs.map(c=>[c.id,c.name+' · '+c.version]),'nis-important')+'</div><div class="dialog-note">Questa operazione sostituisce il lavoro di sessione. Scarica prima il file corrente se vuoi conservarlo. Le valutazioni iniziali del nuovo audit saranno tutte “Da valutare”.</div>','<button data-close>Annulla</button><button class="primary" id="create-audit">Crea audit locale</button>');$('#create-audit').onclick=()=>{project={schema:'titanium-lab-2',version:S.version,tool:'titanium',meta:{name:$('#modal [name=newName]').value.trim().slice(0,2000)||'Nuovo audit',scope:'Perimetro da definire',auditor:'',date:C.today()},rows:E.fromCatalog($('#modal [name=newCatalog]').value),history:[],log:[]};commit('Creato audit locale.');filter={q:'',framework:'',status:'',quick:'',domain:''};$('#modal').close();navigate('audit');};},import:()=>pickFile('.xlsx,.csv',importFile),'export-xlsx':()=>exportXLSX().catch(e=>toast(e.message)),'export-actions':()=>C.download('TITANIUM-piano-azioni.csv',C.csv([['Framework','Codice','Esito','Severita','Priorita','Motivazione priorita','Azione','Responsabile','Scadenza','Stato azione'],...scoped().filter(r=>r.action).map(r=>[r.framework,r.code,r.status,r.severity,E.priority(r).value,E.priority(r).reasons.join('; '),r.action,r.owner,r.due,r.actionStatus])]),'text/csv;charset=utf-8'),'clear-filters':()=>{filter={q:'',framework:'',status:'',quick:'',domain:''};page=0;render();},snapshot:()=>{if(!scoped().length){toast('Seleziona almeno un requisito.');return;}E.snapshot(project,scoped());dirty=true;render();toast('Rilevazione registrata nel lavoro locale.');},print:()=>{const full=$('#report-full')?.checked??true;$('#print-report').innerHTML=reportContent(full);window.print();},'source-info':sourceInfo};
$('#app').onclick=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;try{if(b.dataset.nav){navigate(b.dataset.nav);return;}if(b.dataset.act){actionsMap[b.dataset.act]?.();return;}if(b.dataset.edit){edit(b.dataset.edit);return;}if(b.dataset.add){addCatalog(b.dataset.add);return;}if(b.dataset.status){filter.status=b.dataset.status;filter.framework=b.dataset.frame||'';filter.quick='';navigate('audit');return;}if(b.dataset.quick){quick(b.dataset.quick);return;}if(b.dataset.heat){quick('heat:'+b.dataset.heat);return;}if(b.dataset.due){quick('due:'+b.dataset.due);return;}if(b.dataset.page){page+=Number(b.dataset.page);if(page<0)page=0;render();}}catch(err){toast(err.message);}};
$('#modal').addEventListener('close',()=>{$('#modal').onchange=null;});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});window.TitaniumLab={project:()=>C.clone(project),metrics:()=>E.metrics(scoped()),prepareReport:(full=true)=>reportContent(full),importFile,exportXLSX};render();
})();
